/** GENERATED AV scripts/handbok-html.mjs (pandoc) - ikke rediger for hånd. */

export const brukerhandbokHtml = "<h1 id=\"liturgi--brukerhåndbok\">Liturgi – brukerhåndbok</h1>\n<p>Denne håndboken dokumenterer appen i sin helhet: alle moduler, alle\nfunksjoner og hvordan alt henger sammen. For arkitektur og kodebase se\n<a href=\"api.md\">api.md</a>.</p>\n<p>Liturgi finnes i to varianter som fungerer likt:</p>\n<ul>\n<li><strong>Mac-app (Electron)</strong> – gudstjenester og lokale maler\nlagres som filer; innstillinger i SQLite.</li>\n<li><strong>Nettleser-versjon</strong> – alt lagres i nettleserens\nlocalStorage.</li>\n</ul>\n<hr />\n<h2 id=\"oversikt-modulene-i-appen\">Oversikt: modulene i appen</h2>\n<p><img src=\"bilder/redigering.webp\"\nalt=\"Redigeringsvisningen med sidefeltet, fanene og leddkortene\" /></p>\n<p>Appen består av følgende hoveddeler:</p>\n<table>\n<thead>\n<tr>\n<th>Modul</th>\n<th>Hvor</th>\n<th>Hva den gjør</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Sidefelt (Sidebar)</strong></td>\n<td>venstre</td>\n<td>Hjem, Bibliotek, Kirkeåret, Innstillinger + listen over åpne\ndokumenter</td>\n</tr>\n<tr>\n<td><strong>Redigering</strong></td>\n<td>hovedvindu</td>\n<td>Redigering av gudstjenesten eller malen – ledd for ledd</td>\n</tr>\n<tr>\n<td><strong>Oversikt</strong></td>\n<td>hovedvindu</td>\n<td>Kompakt strukturvisning av hele gudstjenesten</td>\n</tr>\n<tr>\n<td><strong>Salmer</strong></td>\n<td>hovedvindu</td>\n<td>Salmeoversikt: alle salmer med nummer, tittel og tekst</td>\n</tr>\n<tr>\n<td><strong>Eksport</strong></td>\n<td>hovedvindu</td>\n<td>Profilvalg, per-ledd valg, forhåndsvisning og eksport til\nPDF/Word/PPTX</td>\n</tr>\n<tr>\n<td><strong>Maler</strong></td>\n<td>visning</td>\n<td>Liste over innebygde og lokale maler; import og konvertering</td>\n</tr>\n<tr>\n<td><strong>Bibliotek</strong></td>\n<td>visning</td>\n<td>Søk i hovedgudstjenesten; hent innhold eller hele ledd</td>\n</tr>\n<tr>\n<td><strong>Kirkeåret</strong></td>\n<td>visning</td>\n<td>Kirkeårsdager, dagens bønn og bibeltekster\n(forberedelsesvisning)</td>\n</tr>\n<tr>\n<td><strong>Innstillinger</strong></td>\n<td>visning</td>\n<td>Appinnstillinger, profilvalg, brukerhåndbok</td>\n</tr>\n<tr>\n<td><strong>Malverktøy</strong></td>\n<td>visning (dev)</td>\n<td>Redigering av originalmalene direkte i prosjektet (kun\ndev-utgaven)</td>\n</tr>\n<tr>\n<td><strong>Diff</strong></td>\n<td>visning (dev)</td>\n<td>Sammenligning av maler (kun dev-utgaven)</td>\n</tr>\n<tr>\n<td><strong>Kommandopalett</strong></td>\n<td>⌘K</td>\n<td>Søk og kjør alle menyvalg</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Visninger:</strong> appen styres av en\n<code>visning</code>-variabel (<code>hjem</code>, <code>maler</code>,\n<code>bibliotek</code>, <code>innstillinger</code>,\n<code>oversikt</code>, <code>salmer</code>, <code>eksport</code>,\n<code>editor</code>, <code>malverktoy</code>, <code>diff</code>,\n<code>handbok</code>). Hver visning rendres av sin egen Svelte-modul, og\nnavigasjonen (sidefelt, menylinje, kommandopalett) setter bare denne\nvariabelen.</p>\n<hr />\n<h2 id=\"maler-og-bibliotek\">Maler og bibliotek</h2>\n<p><img src=\"bilder/maler.webp\"\nalt=\"Malbiblioteket med filtermeny\" /></p>\n<h3 id=\"maler\">Maler</h3>\n<p>En <strong>mal</strong> er en gudstjenesteskjelett: seksjoner med\nledd, alternativer, roller og instruksjoner. Appen leveres med innebygde\nmaler («Ordning for hovedgudstjeneste (bokmål, 2020)», «Gudstjenestemal\nBakke og Gylland 2025», gravferd, dåp m.fl.), og du kan lage dine egne\nlokale maler.</p>\n<ul>\n<li><strong>Innebygde maler</strong> ligger i appen\n(<code>src/lib/data.js</code>) og følger med alle installasjoner. De er\nlåste: åpner du en, lager endringer en kopi i dine brukermaler.</li>\n<li><strong>Lokale maler</strong> lagres som <code>.limal</code>-filer i\n<code>~/.config/Liturgi/maler/</code> (Mac) og kan dels fritt dels med\nandre.</li>\n<li><strong>Lagre gudstjeneste som mal</strong>: fra en åpnet\ngudstjeneste lagrer du den som grunnordning med «Lagre som mal».</li>\n</ul>\n<h3 id=\"oppbygning-av-en-mal\">Oppbygning av en mal</h3>\n<p>En mal består av <strong>seksjoner</strong> («I. Samling», «II.\nOrdet» …) som igjen består av <strong>ledd</strong>. Hvert ledd har:</p>\n<ul>\n<li><strong>Overskrift</strong> – vises i manuset og kan vises på\nslidene («Leddtitler»).</li>\n<li><strong>Tekst</strong> – liturgisk riktekst (rollemerker, BIBELREF,\nFOTNOTE, @NOTAT, markdown – se <a href=\"#tekstformat\">Tekstformat</a>\nnederst).</li>\n<li><strong>Instruksjonsfelt</strong> – scenenotat til medarbeideren\n(rød kursiv, valgfritt).</li>\n<li><strong>Alternativer</strong> – ett eller flere tekstalternativer\nmed «Bytt alternativ»-velger.</li>\n<li><strong>Innledning/avslutning</strong> – egne grupper for tekster\nsom går foran/etter hoveddelen (f.eks. «L | Vår Herre sier …» før og\n«Slik lyder …» etter). Et ledd kan ha flere\ninnledningsalternativer.</li>\n<li><strong>Rollemerker</strong> – <code>L |</code>, <code>ML |</code>,\n<code>A |</code> osv. (rødt i visningen).</li>\n<li><strong>Type</strong> – tekst, salme (med nummer/tittel og\ntekstfelt) eller lesning (bibeltekst).</li>\n</ul>\n<h3 id=\"lenket-innhold\">Lenket innhold</h3>\n<p>Noen ledd i hovedgudstjenesten er <strong>lenket til en mal</strong>\n– typisk dåpsleddene, som er lenket til dåp-malen. Når malen endres,\nsynkroniseres lenkede ledd i åpne gudstjenester automatisk («lenke-synk»\nsom logges i konsollen). Slik holder lokal tilpasning og hovedmalen seg\ni samsvar uten manuelt vedlikehold. Lenken lagres i gudstjenestefilen;\nbryter du lenken, blir leddet et vanlig fritt ledd.</p>\n<h3 id=\"dynamiske-ledd\">Dynamiske ledd</h3>\n<p>Ledd som fylles av kirkeåret (dagens bønn, bibeltekstene) kalles\n<strong>dynamiske</strong>:</p>\n<ul>\n<li><strong>Dagens bønn</strong> fylles som plassholderfylling\n(<code>[Dagens bønn]</code>), som nytt alternativ («Dagens bønn\n(kirkeåret)») eller som eget ledd – avhengig av hvordan malen er satt\nopp.</li>\n<li><strong>Bibeltekstene</strong> (lesningene) fylles med referanse og\ntekst, og tekstene kan hentes på nytt når som helst (se <a\nhref=\"#ny-gudstjeneste-og-kirkeåret\">Ny gudstjeneste og\nkirkeåret</a>).</li>\n<li>Malen kan ha <strong>dynamisk kobling</strong>:\n<code>Bibeltekster</code>-innstillingen i malen kobler et ledd til\nL1/L2/E, slik at riktig lesning havner i riktig ledd uansett\nkirkeårsdag.</li>\n</ul>\n<h3 id=\"alternativer-og-varianter\">Alternativer og varianter</h3>\n<ul>\n<li><strong>Alternativer</strong> er ulike tekster for samme ledd –\nf.eks. to prekefbønner eller to bekjennelser. Velges med «Bytt\nalternativ (1 av N)».</li>\n<li><strong>Enten/eller-varianter</strong> (bare i bokmålsmalen)\nmarkeres i malen og gjenkjennes ved konvertering.</li>\n<li><strong>Innlednings- og avslutningsalternativer</strong> er egne\ngrupper – et ledd kan bytte både innledning og hoveddel uavhengig av\nhverandre.</li>\n</ul>\n<h3 id=\"bibliotek\">Bibliotek</h3>\n<p><img src=\"bilder/bibliotek.webp\"\nalt=\"Biblioteket: liturgiske tekster og dokumentdeler\" /></p>\n<p>Biblioteket søker i <strong>hovedgudstjenesten</strong> (hele\nliturgien) og kopierer innholdet inn i dokumentet:</p>\n<ul>\n<li><strong>«Hent innhold …»</strong> – erstatter leddets hoveddel med\net valgt alternativ; leddets egen innledning/avslutning og\nalternativgrupper røres ikke.</li>\n<li><strong>«Hent ledd …»</strong> – setter et <strong>nytt\nledd</strong> over det nåværende (mindre destruktivt) med alle\nalternativer, innledning og avslutning fra biblioteket; det nåværende\nleddet fjernes fra gudstjenesten men beholdes i dokumentet.</li>\n</ul>\n<p>Innholdet <strong>kopieres</strong> inn i filen – dokumentet forblir\ndelbart uten referanser til hovedgudstjenesten.</p>\n<hr />\n<h2 id=\"ny-gudstjeneste-og-kirkeåret\">Ny gudstjeneste og kirkeåret</h2>\n<p><img src=\"bilder/hjem.webp\"\nalt=\"Hjem-visningen viser kommende søndag med kollektbønn og bibeltekster\" /></p>\n<ol type=\"1\">\n<li><strong>«Ny gudstjeneste …»</strong> (⌘N) åpner valget av mal, navn\nog dato. Navneforslaget er «dato - type - kirkeårsdag».</li>\n<li><strong>Kirkeårsdagen</strong> slås opp automatisk fra datoen\n(manuell overstyring er mulig). Kirkeårsdagen lagres i gudstjenesten\nsammen med tekstrekke og liturgisk farge.</li>\n<li>Ved opprettelse fyller appen <strong>dagens bønn</strong> og\n<strong>bibeltekstene</strong> fra kirkeåret, med malens struktur i\nbehold (innledning/hoveddel/avslutning).</li>\n<li><strong>Endres datoen</strong> senere spør appen om innholdet skal\noppdateres til den nye kirkeårsdagen – det skjer aldri automatisk.</li>\n<li><strong>Hente bibeltekster på nytt</strong>: høyreklikk et\nlesningsledd → «Hent bibeltekster på nytt», eller bruk kommandopaletten\n(⌘K). Appen slår opp kirkeårsdagen og fyller alle lesningsledd:\nbibelteksten i hoveddelen, referansen i innledningens «Det står skrevet\ni/hos …», avslutningen fra malen. Dagens bønn røres ikke.</li>\n<li><strong>Kirkeåret-visningen</strong> viser kirkeårsdagene, dagens\nbønn og bibeltekstene som forberedelsesmateriell (tekstene hentes i\nbakgrunnen og foldest ut ved behov).</li>\n</ol>\n<hr />\n<h3 id=\"bakgrunnscaching-av-bibeltekster\">Bakgrunnscaching av\nbibeltekster</h3>\n<p>Ved oppstart henter appen i bakgrunnen bibeltekstene for hele\nkirkeåret og de andre tekstrekkene (den kommende kirkeårsdagen først, så\nresten av kirkeåret, deretter nabokirkeårene og til slutt merkedagene).\nHentingen er rolig og sekvensiell med hvile mellom hver forespørsel til\nbibel.no, og kjører helt i bakgrunnen. Kirkeåret-modulen viser en\nfremdriftsindikator mens hentingen pågår. Etter første henting fungerer\nalt offline. Lukker du appen midt i hentingen, fortsetter den der den\nslapp ved neste oppstart.</p>\n<p><img src=\"bilder/kirkeaar.webp\"\nalt=\"Kirkeåret: dagens bønn, bibeltekster og tekstcache-indikator\" /></p>\n<h2 id=\"redigeringsvisningen\">Redigeringsvisningen</h2>\n<p><img src=\"bilder/redigering.webp\"\nalt=\"Redigering: hvert ledd er et kort med verktøylinje og alternativer\" /></p>\n<p>Redigeringsvisningen viser gudstjenesten ledd for ledd, seksjon for\nseksjon. Alt redigeres ved klikk – appen skiller mellom visning (ferdig\nrendret tekst) og redigering (kildetekst med «Vis kildekode»).</p>\n<h3 id=\"verktøylinjen\">Verktøylinjen</h3>\n<ul>\n<li><strong>Vis roller / Vis instruksjoner / Vis salmeinfo</strong> –\nstyrer visningen (og er grunnlaget for eksportens tilsvarende\nvalg).</li>\n<li><strong>Vim-modus</strong> (valgfritt) – tastaturnavigasjon av\nleddene.</li>\n</ul>\n<h3 id=\"hvert-ledd\">Hvert ledd</h3>\n<ul>\n<li><strong>Hovedboksen</strong> (avkrysningsboksen i leddhodet) styrer\nom leddet er med i gudstjenesten; et fjernet ledd dempes i visningen men\nbeholdes i dokumentet.</li>\n<li><strong>Teksten</strong> redigeres ved klikk. Rollemerker,\nBIBELREF/FOTNOTE/@NOTAT-markører, overskrifter og markdown rendres\nlive.</li>\n<li><strong>Salmeledd</strong> har nummer- og tittelfelt, «Hent tekst»\n(salme.no) og «Tekst»-knappen som viser/redigerer selve salmeteksten med\nvers.</li>\n<li><strong>Lesningsledd</strong> kan bytte mellom «Hele teksten» og\n«Bibelref.» (kun referansen).</li>\n<li><strong>Alternativer</strong> byttes med «Bytt alternativ (1 av\nN)».</li>\n<li><strong>Innledning/avslutning</strong> vises som egne rader med egne\nbytteknapper.</li>\n</ul>\n<h3 id=\"kontekstmenyen-høyreklikk-på-et-ledd\">Kontekstmenyen (høyreklikk\npå et ledd)</h3>\n<p>Flytt opp/ned · nytt ledd over/under · nytt hovedavsnitt · hent\ninnhold/ledd fra biblioteket · hent bibeltekster på nytt (lesninger) ·\nskift type · legg til/fjern instruksjonsfelt · vis\nroller/instruksjoner/salmeinfo · fjern fra gudstjenesten / ta med ·\neksportér · slett.</p>\n<h3 id=\"lenkede-ledd\">Lenkede ledd</h3>\n<p>Ledd lenket til en mal (dåpen) synkroniseres automatisk når malen\nendres. Synkroniseringen logges; du kan fjerne lenken ved å redigere\nleddet fritt.</p>\n<hr />\n<h2 id=\"oversikt-og-salmer\">Oversikt og salmer</h2>\n<p><img src=\"bilder/oversikt.webp\"\nalt=\"Oversikten viser hele gudstjenesten i kompakt struktur\" /></p>\n<ul>\n<li><strong>Oversikt</strong> viser hele gudstjenesten kompakt med\nseksjoner og leddoverskrifter – rask navigering og helhetssjekk.</li>\n<li><strong>Salmer</strong> viser alle salmer med nummer, tittel og\ntekst – og er utgangspunktet for å sjekke at sanginnholdet er komplett\nfør eksport.</li>\n</ul>\n<hr />\n<h2 id=\"eksportmodulen\">Eksportmodulen</h2>\n<p><img src=\"bilder/eksport-skjerm.webp\"\nalt=\"Eksport med Skjerm-profilen: lysbildeforhåndsvisning og profiler\" /></p>\n<p>Eksportmodulen har profiler, per-ledd valg og forhåndsvisning.\n<strong>Forhåndsvisningen er førende</strong>: den genereres av samme\nlayoutmotor som eksporten.</p>\n<h3 id=\"profiler\">Profiler</h3>\n<table>\n<thead>\n<tr>\n<th>Profil</th>\n<th>Innhold</th>\n<th>Formater</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Prest</strong></td>\n<td>Full liturgi med instruksjoner</td>\n<td>PDF, Word</td>\n</tr>\n<tr>\n<td><strong>Medarbeider</strong></td>\n<td>Liturgi med instruksjoner og lysbildenumre</td>\n<td>PDF, Word</td>\n</tr>\n<tr>\n<td><strong>Menighet</strong></td>\n<td>Menighetsinnhold (hovedsakelig A/M-roller + salmer), bibeltekster\nsom referanse</td>\n<td>PDF, Word</td>\n</tr>\n<tr>\n<td><strong>Skjerm</strong></td>\n<td>PowerPoint til skjerm</td>\n<td>PPTX (+ lysbildemanus)</td>\n</tr>\n</tbody>\n</table>\n<p>Alle profiler har egne innstillinger (format, kolonner, marger,\navstand, skriftskala) som lagres per dokument.</p>\n<h3 id=\"per-ledd-valg\">Per-ledd valg</h3>\n<p>I eksportlistens leddrader styrer du per ledd og per profil:</p>\n<ul>\n<li><strong>Hovedboksen</strong> – leddet med eller ikke.</li>\n<li><strong>Innhold med/uten</strong> – hele hoveddelen eller bare\noverskriften.</li>\n<li><strong>Innledning med/uten</strong> og <strong>Avslutning\nmed/uten</strong> – for ledd med innledning/avslutning i malen\n(Skjerm/Menighet).</li>\n<li><strong>Hele teksten / Bibelref.</strong> – for bibelledd.</li>\n</ul>\n<p>Valgene lagres per profil i dokumentet.</p>\n<h3 id=\"blanke-sider-skjerm\">Blanke sider (Skjerm)</h3>\n<p>Dropdownen «Blanke» styrer tomme mellomsider i presentasjonen:</p>\n<ul>\n<li><strong>Ingen</strong> – ingen blanke sider.</li>\n<li><strong>Alle</strong> – blank side mellom hvert viste ledd.</li>\n<li><strong>Smart</strong> – blank side kun der det ligger skjulte ledd\nmellom viste ledd, eller der et ledds innledning/avslutning er valgt\nbort. Flere skjulte elementer etter hverandre gir likevel bare én blank\nside. Det kan også komme en blank side til slutt dersom siste ledd har\nskjult avslutning.</li>\n</ul>\n<p>Forhåndsvisningen og pptx-eksporten bruker samme slidplan, så\nfordelingen er alltid identisk.</p>\n<h3 id=\"lysbildemanus\">Lysbildemanus</h3>\n<p>Med «Lysbildemanus» påslått eksporteres samtidig en\nMedarbeider-utskrift med <strong>lysbildenummer i margen</strong> –\nplassert ved det leddet/verset der hvert lysbilde begynner, også for\nblanke mellomsider. Manuset eksporteres som PDF og/eller Word etter\nformatvalgene.</p>\n<h3 id=\"forhåndsvisning\">Forhåndsvisning</h3>\n<ul>\n<li>PDF-profilene: sidevisning generert av samme layoutmotor som\nPDF-eksporten.</li>\n<li>Skjerm: slidevisning generert av samme slidplan som pptx-eksporten,\nmed notatfelt per slide og klikk som markerer tilhørende ledd i\nlisten.</li>\n</ul>\n<h3 id=\"eksportér\">Eksportér</h3>\n<p>«Eksportér kun [profil]» eller «Eksportér alle profilene».\nFilnavn-format: «dato - navn - profil».</p>\n<hr />\n<h2 id=\"innstillinger\">Innstillinger</h2>\n<p><img src=\"bilder/innstillinger.webp\" alt=\"Innstillinger\" /></p>\n<p>Innstillinger (⌘,) samler:</p>\n<ul>\n<li><strong>Versjon og byggnr</strong> – «Versjon 0.0.4 · bygg\nYYYYMMDD.HHMM».</li>\n<li><strong>Appinnstillinger</strong> – maalformer, visninger, hentede\nteksters cache og påloggingsopplysninger for bibel.no/salme.no (lagres\nlokalt).</li>\n<li><strong>Brukerhåndbok</strong> – åpner denne håndboken i appen (også\ni menylinjen under «Hjelp»).</li>\n</ul>\n<p>Innstillinger lagres i SQLite\n(<code>~/.config/Liturgi/liturgi.db</code>) i Mac-appen og i\nlocalStorage i nettleser-versjonen.</p>\n<hr />\n<h2 id=\"kommandopaletten\">Kommandopaletten</h2>\n<p><img src=\"bilder/kommandopalett.webp\"\nalt=\"Kommandopaletten (⌘K)\" /></p>\n<p><strong>⌘K</strong> åpner kommandopaletten: søk i alle menyvalg –\nfilhandlinger, navigasjon, eksportvalg og henting av bibeltekster. ↑↓\nvelger, ⏎ kjører, esc lukker. Paletten har samme handlinger som\nmenylinjen og er kontekstavhengig (eksportvalg vises bare i\neksportvisningen osv.).</p>\n<hr />\n<h2 id=\"malredigering\">Malredigering</h2>\n<p>Maler redigeres som gudstjenester – samme editor, samme kontekstmeny,\nmed noen mal-spesifikke tillegg:</p>\n<ul>\n<li><strong>Innledning/avslutning</strong> kan opprettes og fjernes som\ngrupper (tannhjulsmenyen administrerer alternativene; plussteg legger\ntil nye).</li>\n<li><strong>Alternativgrupper</strong> opprettes, nummereres og\nadministreres per ledd.</li>\n<li><strong>Dynamiske koblinger</strong>: malens\n«Bibeltekster»-innstilling kobler lesningsledd til L1/L2/E.</li>\n<li><strong>Lenket innhold</strong>: hovedgudstjenestens dåpsledd lenkes\ntil dåp-malen; endringer i malen synkroniseres til lenkede ledd i åpne\ngudstjenester.</li>\n<li><strong>Lagre til prosjektet (⌘S)</strong> gjelder bare\noriginalmalene i dev-modus; lokale maler lagres som filer.</li>\n<li><strong>Målform skrives aldri i malens navn</strong> – maalformen\nstyres av innholdet og profilens målformvalg.</li>\n</ul>\n<hr />\n<h2 id=\"dev-modus-og-malverktøy\">Dev-modus og Malverktøy</h2>\n<p>Dev-utgaven bygges kun lokalt (<code>npm run electron:dev</code> /\n<code>build:dev</code>) og inneholder verktøy som aldri følger\npubliserte utgaver. Tre mekanismer holder dem utenfor: byggflagget\n<code>__DEV_MODE__</code> (tree-shaker verktøykoden ut av vanlige bygg),\nupakket-sjekken i hovedprosessen (en app fra DMG får aldri verktøyene)\nog CI-verifisering (release-bygg feiler hvis dev-modulen finnes).</p>\n<h3 id=\"malverktøy\">Malverktøy</h3>\n<p><strong>Malverktøy</strong> redigerer <strong>originalmalene</strong>\n– de innebygde ordningene i <code>src/lib/data.js</code>:</p>\n<ul>\n<li>Åpne en originalmal, rediger med hele den vanlige editoren, og velg\n<strong>«Lagre til prosjektet» (⌘S)</strong>.</li>\n<li>Lagringen skriver tilbake til <code>data.js</code>\n<strong>og</strong> til seed-filen under\n<code>~/.config/Liturgi/maler/</code> med automatisk validering og\ntilbakerulling ved feil.</li>\n<li><strong>Bekreft</strong>-valget fjerner wip-merkingen og låser\nmalen; <strong>Slett</strong> flytter til papirkurven (macOS) med\nbekreftelse.</li>\n<li><strong>Diff</strong>-visningen sammenligner maler mot\noriginalene.</li>\n</ul>\n<h3 id=\"viktig-om-seeds\">Viktig om seeds</h3>\n<p>Endringer i originalmalene lander i <code>src/lib/data.js</code> og\nseed-filene. De blir <strong>ikke</strong> med i fremtidige releaser\nbare ved å ligge lokalt:</p>\n<blockquote>\n<p><strong>Seeds må pushes tilbake til repoet via PR</strong> for å bli\nen del av neste release. Uten push lever endringene kun i din lokale\ndev-utgave og forsvinner ved neste installasjon fra release.</p>\n</blockquote>\n<h3 id=\"frys-vern\">Frys-vern</h3>\n<p>Dev-utgaven og Mac-appen deler ikke data (dev-utgaven kan bruke egen\ndatabase); gudstjenester slettes aldri automatisk – «Slett» flytter\nalltid til papirkurven.</p>\n<hr />\n<h2 id=\"filer-og-lagring\">Filer og lagring</h2>\n<ul>\n<li><strong>Gudstjenester</strong>: <code>.liturgi</code>-filer (JSON) –\nstandard <code>~/Documents/Liturgi/</code>; dobbeltklikk i Finder åpner\nappen.</li>\n<li><strong>Lokale maler</strong>: <code>.limal</code>-filer i\n<code>~/.config/Liturgi/maler/</code>.</li>\n<li><strong>Innstillinger og siste gudstjenester</strong>:\n<code>~/.config/Liturgi/liturgi.db</code> (SQLite).</li>\n<li><strong>«Lagre som …»</strong> duper filen med nytt navn;\n<strong>«Åpne mappe»</strong> viser filen i Finder.</li>\n<li>Sletting flytter alltid til <strong>papirkurven</strong> – aldri\npermanent sletting.</li>\n</ul>\n<hr />\n<h2 id=\"tekstformat\">Tekstformat</h2>\n<p>Tekstene er riktekst med liturgisk markering. Full spesifikasjon: <a\nhref=\"limal-format.md\">docs/limal-format.md</a>.</p>\n<h3 id=\"roller\">Roller</h3>\n<p><code>{{r}}L |{{/r}} tekst</code> (inline-pakket, malenes format)\neller hele linjer: <code>L | tekst</code>, <code>ML/L | tekst</code>,\n<code>@r | tekst</code>. Rollemerket rendres rødt.</p>\n<h3 id=\"linjemarkører\">Linjemarkører</h3>\n<table>\n<thead>\n<tr>\n<th>Markør</th>\n<th>Betydning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>`BIBELREF</td>\n<td>Matt 25,31-46`</td>\n</tr>\n<tr>\n<td>`FOTNOTE</td>\n<td>…`</td>\n</tr>\n<tr>\n<td><code>@NOTAT …</code> / <code>@n …</code></td>\n<td>Scenenotat – rød kursiv, mindre; ikke i menighetsutskrift</td>\n</tr>\n<tr>\n<td><code># / ##</code></td>\n<td>Overskrift / underoverskrift</td>\n</tr>\n<tr>\n<td><code>- punkt</code></td>\n<td>Punktliste</td>\n</tr>\n</tbody>\n</table>\n<h3 id=\"inline\">Inline</h3>\n<p><code>**fet**</code>, <code>*kursiv*</code>, <code>^{1}</code> (hevet\nversnummer), <code>{{refreng}}…{{/refreng}}</code> (kursiv blokk).</p>\n<h3 id=\"linjeskift\">Linjeskift</h3>\n<p>Nye linjer = linjeskift, tomme linjer = avsnitt. Linjer som starter\nmed en markør får eget avsnitt. Linjeskiftene fra redigeringen er\nførende i alle eksporter.</p>\n";
export const apiHtml = "<h1 id=\"liturgi--arkitektur-og-api\">Liturgi – arkitektur og API</h1>\n<p>Denne dokumentasjonen beskriver kodebasen: hvordan appen er bygd opp,\nhva de ulike modulene gjør og hvordan de samarbeider. For brukerrettet\ndokumentasjon se <a href=\"brukerhandbok.md\">brukerhandbok.md</a>.</p>\n<hr />\n<h2 id=\"overordnet-arkitektur\">Overordnet arkitektur</h2>\n<pre><code>┌─────────────────────────────────────────────────────┐\n│ Electron-hovedprosess (electron/main.cjs)           │\n│  · vindu, nativ menylinje, kontekstmeny (Menu.popup)│\n│  · fil-IPC (lagre/åpne .liturgi/.limal)             │\n│  · SQLite (~/.config/Liturgi/liturgi.db)            │\n│  · statisk server + proxy mot bibel.no/salme.no     │\n│  · docx/pdf → .limal-konvertering (konverter.cjs)   │\n└──────────────────────┬──────────────────────────────┘\n                       │ window.liturgi (preload.cjs, contextIsolation)\n┌──────────────────────▼──────────────────────────────┐\n│ SvelteKit-renderer (src/) – Svelte 5 runes          │\n│  · store.svelte.js   – global tilstand              │\n│  · fileio.svelte.js  – filer, menyhandling          │\n│  · export.js         – eksportmotor (PDF/Word/PPTX) │\n│  · routes/+page.svelte – visningsruting             │\n└─────────────────────────────────────────────────────┘</code></pre>\n<ul>\n<li><strong>Rendereren</strong> er en SvelteKit-app med\n<code>adapter-static</code> (<code>ssr = false</code>): hele UI-et er en\nstatisk SPA som Electron serverer lokalt, og som bygges til GitHub Pages\nfor nettleser-versjonen.</li>\n<li><strong>Hovedprosessen</strong> eier alt med OS-tilgang: filsystem,\nSQLite, menyer, dialoger, nettverksproxy og konvertering.</li>\n<li><strong>Mellom dem</strong>: en smal bridge\n(<code>preload.cjs</code> → <code>window.liturgi</code>) med\ncontextIsolation.</li>\n</ul>\n<h3 id=\"visningsruting\">Visningsruting</h3>\n<p><code>src/routes/+page.svelte</code> ruter på\n<code>app.visning</code>:</p>\n<table>\n<thead>\n<tr>\n<th>Visning</th>\n<th>Modul</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>hjem</code></td>\n<td>Hjem-skjerm</td>\n</tr>\n<tr>\n<td><code>editor</code></td>\n<td>Redigeringsvisning</td>\n</tr>\n<tr>\n<td><code>oversikt</code> / <code>salmer</code></td>\n<td>Oversikt / salmeoversikt</td>\n</tr>\n<tr>\n<td><code>eksport</code></td>\n<td>Eksportmodulen (<code>Eksport.svelte</code>)</td>\n</tr>\n<tr>\n<td><code>maler</code> / <code>bibliotek</code> /\n<code>innstillinger</code></td>\n<td>egne visninger</td>\n</tr>\n<tr>\n<td><code>malverktoy</code> / <code>diff</code></td>\n<td>dev-moduler (<code>__DEV_MODE__</code>-beskyttet)</td>\n</tr>\n<tr>\n<td><code>handbok</code></td>\n<td>Brukerhåndboken (renderer docs/brukerhandbok.md)</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h2 id=\"dataformater\">Dataformater</h2>\n<h3 id=\"liturgi--gudstjenestefil\"><code>.liturgi</code> –\ngudstjenestefil</h3>\n<p>JSON-dokument:</p>\n<div class=\"sourceCode\" id=\"cb2\"><pre\nclass=\"sourceCode json\"><code class=\"sourceCode json\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">{</span></span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;name&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;2026-11-29 - Bakke - Gudstjeneste&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;date&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;2026-11-29&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;kirkeaar&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;name&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;1. søndag i advent&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;series&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;A&quot;</span> <span class=\"fu\">},</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;sections&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span></span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\" tabindex=\"-1\"></a>    <span class=\"fu\">{</span> <span class=\"dt\">&quot;title&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;I. Samling&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;items&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;id&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;type&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;tekst|salme|lesning&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\" tabindex=\"-1\"></a>        <span class=\"dt\">&quot;heading&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;instr&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;enabled&quot;</span><span class=\"fu\">:</span> <span class=\"kw\">true</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\" tabindex=\"-1\"></a>        <span class=\"dt\">&quot;alts&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span><span class=\"fu\">{</span> <span class=\"dt\">&quot;label&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span><span class=\"ot\">]</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;selAlt&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">0</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\" tabindex=\"-1\"></a>        <span class=\"dt\">&quot;introAlts&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span><span class=\"fu\">{</span> <span class=\"dt\">&quot;label&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Innledning&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span><span class=\"ot\">]</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;selIntro&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">0</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-10\"><a href=\"#cb2-10\" aria-hidden=\"true\" tabindex=\"-1\"></a>        <span class=\"dt\">&quot;avslutningAlts&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span><span class=\"fu\">{</span> <span class=\"dt\">&quot;label&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Avslutning&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span><span class=\"ot\">]</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;selAvsl&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">0</span> <span class=\"fu\">}</span> <span class=\"ot\">]</span> <span class=\"fu\">}</span></span>\n<span id=\"cb2-11\"><a href=\"#cb2-11\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"ot\">]</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-12\"><a href=\"#cb2-12\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;eksportValg&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;Menighet&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;0:2&quot;</span><span class=\"fu\">:</span> <span class=\"kw\">false</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;0:7:t&quot;</span><span class=\"fu\">:</span> <span class=\"kw\">false</span> <span class=\"fu\">}</span> <span class=\"fu\">},</span></span>\n<span id=\"cb2-13\"><a href=\"#cb2-13\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;eksportInnst&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;Skjerm&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;storrelse&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span> <span class=\"fu\">},</span></span>\n<span id=\"cb2-14\"><a href=\"#cb2-14\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;eksportPptx&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;lysManus&quot;</span><span class=\"fu\">:</span> <span class=\"kw\">true</span> <span class=\"fu\">}</span></span>\n<span id=\"cb2-15\"><a href=\"#cb2-15\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">}</span></span></code></pre></div>\n<p>Nøkkelkonvensjoner: leddnøkler er <code>\"seksjon:item\"</code>\n(<code>\"0:2\"</code>); tilleggsnøkler peker på samme ledd med suffix —\n<code>:t</code> (innhold), <code>:i</code> (innledning), <code>:a</code>\n(avslutning), <code>:br</code> (bibelreferanse-modus). Tekstene bruker\nliturgisk riktekst (se <a\nhref=\"limal-format.md\">limal-format.md</a>).</p>\n<h3 id=\"limal--malfil\"><code>.limal</code> – malfil</h3>\n<p>Samme struktur som <code>.liturgi</code>, pluss mal-metadata.\nFormatet er dokumentert fullstendig i <a\nhref=\"limal-format.md\">docs/limal-format.md</a> — kilden til sannheten\nfor malformatet, brukt av konverteringen og LLM-skillen.</p>\n<hr />\n<h2 id=\"moduloversikt\">Moduloversikt</h2>\n<h3 id=\"electron\">electron/</h3>\n<table>\n<thead>\n<tr>\n<th>Fil</th>\n<th>Ansvar</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>main.cjs</code></td>\n<td>Vindu, mac-menylinje (<code>byggMeny</code>), nativ kontekstmeny,\nfil-IPC, SQLite-tilgang, proxy mot bibel.no/salme.no, feillogg,\nmenytilstand (<code>app:meny-tilstand</code> →\n<code>meny:handling</code>)</td>\n</tr>\n<tr>\n<td><code>preload.cjs</code></td>\n<td>Bridge <code>window.liturgi</code> (contextIsolation)</td>\n</tr>\n<tr>\n<td><code>db.cjs</code></td>\n<td>SQLite: innstillinger (<code>dbSet/dbGet</code>), siste\ngudstjenester, maler-index</td>\n</tr>\n<tr>\n<td><code>konverter.cjs</code></td>\n<td>docx/pdf → <code>.limal</code>: hoveddeler/leddtitteler fra stiler,\nrolleprefiks, `BIBELREF</td>\n</tr>\n</tbody>\n</table>\n<h3 id=\"srclib--kjerne\">src/lib/ – kjerne</h3>\n<table>\n<thead>\n<tr>\n<th>Fil</th>\n<th>Ansvar</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>store.svelte.js</code></td>\n<td>Global tilstand (Svelte 5 <code>$state</code>): åpne dokumenter,\nvisning, kirkeårsfylling (<code>applyKirkeaar</code>,\n<code>fyllLesning</code> via <code>lit.js</code>), formatering av bønn,\nmalregistrering</td>\n</tr>\n<tr>\n<td><code>fileio.svelte.js</code></td>\n<td>Lagre/åpne filer, <code>saveCurrent</code>, <code>kjorMenyId</code>\n(menylinje/kommandopalett → handling), siste-gudstjenester, maler på\ndisk</td>\n</tr>\n<tr>\n<td><code>export.js</code></td>\n<td>Hele eksportmotoren (se <a\nhref=\"#eksportarkitekturen\">Eksportarkitekturen</a>)</td>\n</tr>\n<tr>\n<td><code>lit.js</code></td>\n<td>Tekstrendering og -hjelpere: <code>roleSegments</code>\n(rolle/markdown/sup-segmenter),\n<code>litHtml</code>/<code>litLinjeHtml</code> (HTML-render),\n<code>leddTekst</code> (komponert ledtekst m/ innledning+avslutning),\n<code>salmeTekst</code>, <code>fyllLesning</code> (bibeltekst-struktur),\n<code>referanseIInnledning</code></td>\n</tr>\n<tr>\n<td><code>deler-logikk.js</code></td>\n<td>Ren logikk for eksportlistens utvalg (<code>secAlternativer</code>,\n<code>includeSection</code>, <code>filterValgfrie</code>) –\nre-eksportert av store</td>\n</tr>\n<tr>\n<td><code>kirkeaar.js</code></td>\n<td>Kirkeårsdata, oppslag av dag fra dato (<code>lookupKirkeaar</code>),\nbibeltekst-henting fra bibel.no (<code>hentTekster</code>), cache\n(<code>lesTeksterCache</code>)</td>\n</tr>\n<tr>\n<td><code>data.js</code></td>\n<td>Innebygde maler (BUILTIN_TEMPLATES) – generert fra originalene</td>\n</tr>\n<tr>\n<td><code>malverktoy.svelte.js</code></td>\n<td>Dev: åpne/lagre originalmaler, seed-skriving til\n<code>data.js</code> + seed-fil</td>\n</tr>\n<tr>\n<td><code>contextmenu.svelte.js</code></td>\n<td>Renderer-eid kontekstmeny (delegerer til nativ meny i Electron)</td>\n</tr>\n<tr>\n<td><code>modal.svelte.js</code></td>\n<td>Alle dialoger (velgModal, chooseOneModal, bibSokModal,\nkirkeaarListeModal …)</td>\n</tr>\n<tr>\n<td><code>mdi.js</code> / <code>sf.js</code></td>\n<td>Ikonpath-data offline (MDI / SF Symbols)</td>\n</tr>\n<tr>\n<td><code>bibelboeker.js</code></td>\n<td>Hjelpeoppslag for bibelbøker (referanse-validering)</td>\n</tr>\n</tbody>\n</table>\n<h3 id=\"srclib--visninger\">src/lib/ – visninger</h3>\n<p><code>Sidebar.svelte</code>, <code>Editor.svelte</code> +\n<code>Item.svelte</code> (ett ledd), <code>Eksport.svelte</code>\n(profiler, per-ledd valg, forhåndsvisning, eksport),\n<code>Kirkeaar.svelte</code>, <code>Bibliotek.svelte</code>,\n<code>Innstillinger.svelte</code>, <code>Malverktoy.svelte</code>,\n<code>Kommandopalett.svelte</code>, <code>Handbok.svelte</code>\n(brukerhåndboken), <code>Modal.svelte</code> (ny gudstjeneste m.m.),\n<code>EditableText.svelte</code> (klikk-til-rediger riktekst).</p>\n<hr />\n<h2 id=\"tilstand-og-lagring\">Tilstand og lagring</h2>\n<p><strong>App-tilstand</strong> (<code>store.svelte.js</code>):\n<code>app = { visning, kind ('service'|'template'|null), current, åpneTjenester, services, dirty … }</code>\n— alt som <code>$state</code>-proxyer, så Svelte 5-runes reagerer på\ndype endringer.</p>\n<p><strong>Persistens</strong>:</p>\n<ul>\n<li>Mac: <code>.liturgi</code>/<code>.limal</code>-filer via\n<code>window.liturgi.lagre/åpne</code> (hovedprosess); innstillinger i\nSQLite via <code>dbSet/dbGet</code> med JSON-pakking.</li>\n<li>Nettleser: samme struktur i localStorage (fallback/normalisering ved\noppstart).</li>\n<li><code>markDirty()</code> setter dirty-flagg og driver\nautolagring/avsluttingsbekreftelse («ulagrede endringer»).</li>\n</ul>\n<p><strong>Menyhåndtering</strong>: menylinjen (Electron) og\nkommandopaletten sender meny-id-er til <code>kjorMenyId(id)</code> i\n<code>fileio.svelte.js</code> — ett switch-punkt som mapper id →\nhandling. Kontekstmenyer sender egne id-er til\n<code>window.__eksMeny</code>/lokale handlere.</p>\n<hr />\n<h2 id=\"eksportarkitekturen\">Eksportarkitekturen</h2>\n<p><code>src/lib/export.js</code> inneholder hele eksportmotoren.\nGrunnprinsippet: <strong>én layoutkilde per medie, og forhåndsvisningen\nbruker eksportmotoren</strong>.</p>\n<h3 id=\"pptx-skjerm\">PPTX (Skjerm)</h3>\n<pre><code>byggSlidePlan(svc, valg) → plan  ─┬─→ exportPptx()   → pptxgenjs\n                                  └─→ byggPptSlides() → forhåndsvisning (HTML)</code></pre>\n<ul>\n<li><strong><code>byggSlidePlan</code></strong> bygger slidplanen:\ntittelslide, én plan-entry per slide\n(<code>{ segs, big, notat, nokkel, del, blank }</code>), tomme\nmellomsider etter «tomSlideModus»\n(<code>av</code>/<code>alle</code>/<code>smart</code>), salmevers per\ngruppe, ekstra slides, og <code>posisjoner</code>-kartet\n(<code>nokkel → forste/deler</code>) som er grunnlaget for\nmargtallene.</li>\n<li>Blanke-sider-logikken: <code>smart</code> legger inn blank der\nskjulte ledd ligger mellom viste ledd, eller der et ledd har\n<code>__skjultIntro</code>/<code>__skjultAvsl</code> (merket av\n<code>klonMedValg</code> ut fra per-ledd valgene\n<code>:i</code>/<code>:a</code>). Aldri doble blanke; blank etter\ntittelslide og til slutt er tillatt etter samme regler.</li>\n<li><strong><code>delPptSegs(segs, fs)</code></strong> deler segmenter\ntil slide-størrelse med <strong>linjebevisst budsjett</strong> (antall\nrendrete linjer per slide, korte verslinjer teller som hele linjer; kutt\naldri midt i hevet versnummer).</li>\n<li><strong><code>exportPptx</code></strong> rendrer planen med\npptxgenjs: rollefarger, hevet versnummer (sup-run med redusert skrift),\ntomme mellomsider, notater, lys bakgrunn, og rydder pptxgenjs 4.x sitt\n<code>[Content_Types].xml</code>-skjema (slideMaster-Overrides).</li>\n<li><strong>Forhåndsvisningen</strong> (<code>byggPptSlides</code> i\nEksport.svelte) konsumerer samme plan og tegner HTML-slides —\nfordelingen er per definisjon identisk.</li>\n</ul>\n<h3 id=\"pdf-prestmedarbeidermenighet\">PDF\n(Prest/Medarbeider/Menighet)</h3>\n<pre><code>buildPdfBase64(svc, instr, valg) ─┬─→ base64 → lagrePdf()   (PDF-eksport)\n                                  └─→ byggPdfSider()        (forhåndsvisning)</code></pre>\n<ul>\n<li><strong><code>buildPdfBase64</code></strong> er hele\nPDF-layoutmotoren (jsPDF): titler, instruksjoner,\n<code>skrivSegmenter</code>-flyten (linjebryting, hevet versnummer,\nrollefarger, fotnoter), sidestyring, kolonner, marger, avstander.\nInnholdet komponeres per ledd med <code>leddTekst</code> (innledning +\nhoveddel + avslutning, med plassholder- og dobbelt-filtre).</li>\n<li><strong><code>byggPdfSider</code></strong> kjører samme funksjon med\n<code>__spor</code>-instrumentering: hver tegneoperasjon logges, spilles\nav per side og rendres som forhåndsvisningssider. Forhåndsvisningen er\ndermed per definisjon lik eksporten.</li>\n</ul>\n<h3 id=\"word\">Word</h3>\n<p><code>exportWord(svc, instr, filnavn, valg)</code> bygger docx med\ndocx-biblioteket: samme innhold (klonMedValg-kopien), profilens\ninnstillinger (kolonner, marger, avstand), seksjonstitler med linje,\ngruppeflyt for salmer og alternativer, lysbildenumre for\nlysbildemanus.</p>\n<h3 id=\"lysbildemanus\">Lysbildemanus</h3>\n<p><code>lysbildeTallFor(plan, manuscript, ppt)</code> mapper leddnøkler\ntil slidenumre: ledd med egne slides får sitt første nummer (+\n<code>del</code> per gruppe); ledd uten slides får «neste emitterte\nslide − 1» (F-1-regelen — dekker skjulte ledd og blanke sider); blanke\nsider med skjult innledning/avslutning gir tall foran/etter leddets egne\ngrupper (<code>tom</code>-flagg). Tallene tegnes i manuset ved\nvers-/gruppe-start (salmer: ett tall per vers).</p>\n<h3 id=\"per-ledd-valg-og-klonmedvalg\">Per-ledd valg og\n<code>klonMedValg</code></h3>\n<p><code>klonMedValg(svc, profil, brProfil)</code> lager en eksportkopi:\ndokumentnivå <code>enabled</code> respekteres, per-ledd valg leses fra\n<code>lesValg(profil)</code> (Skjerm arver hovedbokser fra det delte\nMenighet-utvalget; egne Skjerm-valg vinner;\n<code>:i</code>/<code>:a</code>/<code>:t</code>/<code>:br</code> arves\nikke). Kopian merkes med\n<code>__visOverskrift</code>/<code>__visInnhold</code>/<code>__skjultIntro</code>/<code>__skjultAvsl</code>/<code>__ref</code>\nog strappes (salmeinfo, innledning/avslutning) — alle eksportformatene\nkonsumerer kopien, så visning og eksport er alltid konsistente.</p>\n<hr />\n<h2 id=\"kirkeåret-og-bibeltekster\">Kirkeåret og bibeltekster</h2>\n<ul>\n<li><code>kirkeaar.js</code>: <code>lookupKirkeaar(dato)</code> →\nkirkeårsdag (navn, rekke, farge, dag-nøkkel);\n<code>hentTekster(day, cache, rekke)</code> henter L1/L2/E + bønn fra\nbibel.no (via hovedprosessen i Mac-appen / vite-proxy i nettleser), med\nlokal cache.</li>\n<li><code>applyKirkeaar(svc, k, tekster)</code> (store.svelte.js) fyller\ndagens bønn og lesningene ved opprettelse og datoendring —\n<strong>alltid med brukerens bekreftelse</strong> ved datoendring.</li>\n<li><code>fyllLesning(it, ref, tekst, evangelium)</code> (lit.js) setter\nstrukturen: bibeltekst i hoveddelen, referanse inn i innledningens\n«…står skrevet i …» (via <code>referanseIInnledning</code> — erstatter\nellipsis eller eksisterende referanse), avslutning fra malen.\nPlassholder-varianter\n(<code>[Lesningstekst]</code>/<code>[Evangelietekst]</code>) og\nfrittstående ledd (B&amp;G) har egne grener.</li>\n<li>Re-henting: <code>hentBibelteksterPåNytt(svc)</code> (store) brukes\nav kontekstmenyen (lesningsledd) og kommandopaletten; fyller alle\nlesningsledd med ny struktur. Dagens bønn røres ikke.</li>\n</ul>\n<hr />\n<h3 id=\"bakgrunnscaching-av-kirkeårsbibeltekster\">Bakgrunnscaching av\nkirkeårsbibeltekster</h3>\n<p>Ved oppstart (<code>tekstcache.js</code>, planlegging i\n<code>tekstcache-plan.js</code>) bygges en prioritert oppgaveliste fra\nkirkeårspakken: kommende kirkeårsdag → resten av det gjeldende kirkeåret\n→ tidligere dager → dager med annen tekststruktur (festdager/unntak) →\nde to nabokirkeårene (de andre tekstrekkene) → merkedager. Hentingen er\nsekvensiell med 1,4 s hvile (lengre pause hvert 15. kall), alt asynkront\ni bakgrunnen. Tekstene lagres per dag i db-nøkkelen\n<code>kirkeaarTekster</code> (samme cache som appen bruker ved henting),\nnoe som gjør prosessen gjenopptakbar: dager som ligger i cachen hoppes\nover ved neste oppstart. Indikatoren vises i Kirkeåret-modulen via\n<code>app.tekstCache</code>.</p>\n<h3 id=\"salmetekst-cache-og-bruksstatistikk\">Salmetekst-cache og\nbruksstatistikk</h3>\n<p><code>electron/salme-cache.cjs</code> cacher salmetekster fra\ngudstjeneste.no i db-nøkkelen <code>salmeCache</code> til etter\ngudstjenestens dato har passert;\n<code>salme:hent</code>/<code>salme:hent-flere</code> returnerer teksten\numiddelbart ved treff. TONO-registreringen kjøres likevel som vanlig —\nved cache-treff i bakgrunnen etter at teksten er levert. Nøkkelen\n<code>salmeBruk</code> fører bruksstatistikk (nummer, tittel, datoer);\nsalmer brukt 3+ ganger de siste 3 månedene beholdes i cachen i 90 dager\ni stedet for til gudstjenestedatoen.</p>\n<h2 id=\"konvertering-og-llm-skill\">Konvertering og LLM-skill</h2>\n<ul>\n<li><strong>Innebygd konvertering</strong> (Maler-siden → «Konverter\nWord/PDF …»): <code>electron/konverter.cjs</code> kjører offline i\nhovedprosessen og oversetter docx/pdf til <code>.limal</code>. Regler:\nhoveddeler fra overskriftstiler, rolleprefiks →\n<code>{{r}}…{{/r}}</code>, bibelreferanser → <code>BIBELREF |</code>,\nrubrikker → <code>@NOTAT</code>, salmelinjer → salmeledd,\nEller/enten-varianter → alternativgrupper. Heuristisk resultat —\netterkontroll i editoren.</li>\n<li><strong>LLM-skill</strong>: <a\nhref=\"https://github.com/ArnstadFredrik/liturgi-limal-skill\">ArnstadFredrik/liturgi-limal-skill</a>\npakker arbeidsflyten for LLM-styrt konvertering. Skillen henter alltid\nsiste format-spesifikasjon fra dette repoet: <a\nhref=\"limal-format.md\"><code>docs/limal-format.md</code></a> — dermed er\nformatet og skriptene aldri eldre i skillen enn i appen.</li>\n</ul>\n<hr />\n<h2 id=\"bygg-release-og-distribusjon\">Bygg, release og distribusjon</h2>\n<table>\n<thead>\n<tr>\n<th>Kommando</th>\n<th>Hva</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>npm run dev</code></td>\n<td>Vite-utviklingsserver (nettleser)</td>\n</tr>\n<tr>\n<td><code>npm run build</code></td>\n<td>Statisk produksjonsbygg (GitHub Pages/web)</td>\n</tr>\n<tr>\n<td><code>npm run build:dev</code></td>\n<td>Dev-bygg (<code>VITE_DEV_MODE=1</code>,\n<code>__DEV_MODE__</code>-flagget)</td>\n</tr>\n<tr>\n<td><code>npm run electron:dev</code></td>\n<td>Dev-bygg + Electron lokalt (port 9230/9310 ved debugging)</td>\n</tr>\n<tr>\n<td><code>npm run app:mac</code></td>\n<td><code>skriv-byggnr.mjs</code> (byggnr = <code>YYYYMMDD.HHMM</code>)\n+ vite build + electron-builder → DMG</td>\n</tr>\n<tr>\n<td><code>npm test</code></td>\n<td>Enhetstester (<code>tests/enhet/</code>)</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Release</strong>: <code>v*</code>-tag → GitHub Actions\nbygger mac/win/linux (node 22, <code>npmRebuild=false</code>),\npubliserer release, oppdaterer Homebrew-tap og GitHub Pages (web) — og\nverifiserer at dev-modulen <strong>ikke</strong> finnes i byggget.</li>\n<li><strong>Byggnr</strong>: skrives per bygg til\n<code>electron/byggnr.txt</code> og vises i Innstillinger («Versjon\n0.0.4 · bygg …»).</li>\n<li><strong>Web-utgaven</strong>: samme SPA med localStorage-lagring;\nrobust lastning av maler ved deploy.</li>\n</ul>\n<hr />\n<h2 id=\"tester\">Tester</h2>\n<p><code>npm test</code> kjører <code>tests/enhet/*.test.mjs</code>\n(node --test). Suksessivt dekket: slidplan (tittel/vers/blanke/moduser),\nlysbildeTallFor (F-1, blanke-tall), delPptSegs (linjebudsjett),\nleddTekst (innledning/avslutning/plassholdere/dobbel-filtre),\nfyllLesning (struktur/referanse/idempotens), bibeltekst-henting,\nmdi-ikoner (alle brukte ikoner finnes), bibliotek-flows. Ny funksjon →\nenhetstest i samme commit.</p>\n";
export const limal_formatHtml = "<h1 id=\"limal--malformat-for-liturgi\">.limal — malformat for\nLiturgi</h1>\n<p>Dette dokumentet er kilden til sannheten for\n<code>.limal</code>-filformatet og liturgistrukturen i Liturgi-appen.\nKonverteringsskript og LLM-skills skal lese denne filen for å hente\nsiste utgave av formatet.</p>\n<p>En <code>.limal</code>-fil er JSON med toppnivå-nøklene\n<code>liturgiFormat: 1</code>, <code>kind: \"template\"</code> og\n<code>data</code> (selve malen). Tilsvarende for gudstjenester:\n<code>.liturgi</code> med <code>kind: \"service\"</code>.</p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode json\"><code class=\"sourceCode json\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">{</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;liturgiFormat&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">1</span><span class=\"fu\">,</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;kind&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;template&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;data&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"er\">…</span> <span class=\"er\">mal-objektet</span> <span class=\"er\">…</span> <span class=\"fu\">}</span></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">}</span></span></code></pre></div>\n<h2 id=\"mal-objektet-data\">Mal-objektet (<code>data</code>)</h2>\n<table>\n<thead>\n<tr>\n<th>Felt</th>\n<th>Type</th>\n<th>Betydning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>id</code></td>\n<td>streng</td>\n<td>stabil id (f.eks. <code>dop-i-hovedgudstjenesten-2017</code>)</td>\n</tr>\n<tr>\n<td><code>name</code></td>\n<td>streng</td>\n<td>visningsnavn, uten målform (f.eks. «Dåp i hovedgudstjenesten\n(2017)»)</td>\n</tr>\n<tr>\n<td><code>description</code></td>\n<td>streng</td>\n<td>valgfri beskrivelse</td>\n</tr>\n<tr>\n<td><code>malForm</code></td>\n<td>streng</td>\n<td>målform/språk: <code>bokmål</code> (standard), <code>nynorsk</code>,\n…</td>\n</tr>\n<tr>\n<td><code>liturgiType</code></td>\n<td>streng</td>\n<td><code>gudstjeneste</code> (standard), <code>vigsel</code>,\n<code>gravferd</code> — avgjør kategori og «Opprett»-liste</td>\n</tr>\n<tr>\n<td><code>kanGudstjeneste</code></td>\n<td>bool</td>\n<td><code>false</code> = malen tilbys ikke ved opprett av\ngudstjeneste</td>\n</tr>\n<tr>\n<td><code>alternativer</code></td>\n<td>string[]</td>\n<td>katalog av alternativ-merker (f.eks.\n<code>[\"dåp\", \"nattverd\"]</code>) som styrer valgene i\n«Opprett»-dialogen</td>\n</tr>\n<tr>\n<td><code>skriftlesningKilde</code></td>\n<td>string</td>\n<td><strong>seksjonstittel i samme mal</strong> som er kilden til\nskriftlesningene (f.eks. \"Skriftlesninger ved Vigsels- og\nforbønnsliturgi 2017\") — brudeparet velger tekster fra denne\nseksjonen</td>\n</tr>\n<tr>\n<td><code>delGrupper</code></td>\n<td>string[]</td>\n<td>katalog av variasjoner/del-grupper (f.eks.\n<code>[\"gravferd\", \"bisettelse\"]</code>) — enten/eller</td>\n</tr>\n<tr>\n<td><code>sections</code></td>\n<td>array</td>\n<td>hoveddelene (se under)</td>\n</tr>\n<tr>\n<td><code>visInstr</code> / <code>visRoles</code> /\n<code>visSalmeinfo</code></td>\n<td>bool</td>\n<td>visningsvalg (standard <code>true</code>)</td>\n</tr>\n<tr>\n<td><code>builtinKey</code></td>\n<td>streng</td>\n<td>bare innebygde originalmaler (ikke med i brukermaler)</td>\n</tr>\n<tr>\n<td><code>erOriginal</code></td>\n<td>bool</td>\n<td>flagg for originalmaler</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"seksjon-hoveddel\">Seksjon (hoveddel)</h2>\n<div class=\"sourceCode\" id=\"cb2\"><pre\nclass=\"sourceCode json\"><code class=\"sourceCode json\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">{</span></span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;title&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;I. Samling&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;items&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span> <span class=\"er\">…</span> <span class=\"er\">ledd</span> <span class=\"er\">…</span> <span class=\"ot\">]</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;alternativer&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span><span class=\"st\">&quot;dåp&quot;</span><span class=\"ot\">]</span><span class=\"fu\">,</span>          <span class=\"er\">//</span> <span class=\"er\">valgfritt</span><span class=\"fu\">:</span> <span class=\"er\">flervalg-merker</span> <span class=\"er\">(alternativer-katalogen)</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"st\">&quot;delGruppe&quot;</span><span class=\"er\">:</span> <span class=\"st\">&quot;gravferd&quot;</span><span class=\"fu\">,</span>          <span class=\"er\">//</span> <span class=\"er\">valgfritt</span><span class=\"fu\">:</span> <span class=\"er\">variasjon</span> <span class=\"er\">(kun</span> <span class=\"er\">én</span> <span class=\"er\">pr</span> <span class=\"er\">mal)</span></span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"st\">&quot;__lenket&quot;</span><span class=\"er\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;malId&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;tittel&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span>  <span class=\"er\">//</span> <span class=\"er\">lenket</span> <span class=\"er\">hoveddel:</span> <span class=\"er\">innholdet</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\" tabindex=\"-1\"></a>                                                <span class=\"er\">//</span> <span class=\"er\">fornyes</span> <span class=\"er\">fra</span> <span class=\"er\">malen</span> <span class=\"er\">ved</span> <span class=\"er\">åpning</span></span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\" tabindex=\"-1\"></a>                                                <span class=\"er\">//</span> <span class=\"er\">og</span> <span class=\"er\">kan</span> <span class=\"er\">ikke</span> <span class=\"er\">redigeres</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">}</span></span></code></pre></div>\n<p>Hoveddeler nummereres ofte med romertall i tittelen\n(<code>I. Samling</code>, <code>II. Ordet</code>,\n<code>III. Nattverd</code>, <code>IV. Sendelse</code>).</p>\n<h2 id=\"ledd-item\">Ledd (item)</h2>\n<div class=\"sourceCode\" id=\"cb3\"><pre\nclass=\"sourceCode json\"><code class=\"sourceCode json\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">{</span></span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;id&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;unik-id&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;type&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;tekst&quot;</span><span class=\"fu\">,</span>                    <span class=\"er\">//</span> <span class=\"dt\">&quot;tekst&quot;</span> <span class=\"er\">|</span> <span class=\"dt\">&quot;salme&quot;</span> <span class=\"er\">|</span> <span class=\"dt\">&quot;instruks&quot;</span></span>\n<span id=\"cb3-4\"><a href=\"#cb3-4\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;heading&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;* 3 Hilsen&quot;</span><span class=\"fu\">,</span>            <span class=\"er\">//</span> <span class=\"er\">leddtittel;</span> <span class=\"er\">`*</span> <span class=\"er\">`</span> <span class=\"er\">=</span> <span class=\"er\">menigheten</span> <span class=\"er\">står</span> <span class=\"er\">under</span> <span class=\"er\">leddet</span> <span class=\"er\">(ikke</span> <span class=\"er\">valgfri)</span></span>\n<span id=\"cb3-5\"><a href=\"#cb3-5\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;bokstav&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;A&quot;</span><span class=\"fu\">,</span>                     <span class=\"er\">//</span> <span class=\"er\">valgfritt</span><span class=\"fu\">:</span> <span class=\"er\">katalog-ledd</span> <span class=\"er\">i</span> <span class=\"er\">skriftlesningskatalog</span> <span class=\"er\">(A</span><span class=\"fu\">,</span> <span class=\"er\">B,</span> <span class=\"er\">C</span> <span class=\"er\">…)</span></span>\n<span id=\"cb3-6\"><a href=\"#cb3-6\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;instr&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;&quot;</span><span class=\"fu\">,</span>                        <span class=\"er\">//</span> <span class=\"er\">instruksjoner/rubrikker</span> <span class=\"er\">(vises</span> <span class=\"er\">kursiv</span> <span class=\"er\">rød)</span></span>\n<span id=\"cb3-7\"><a href=\"#cb3-7\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span><span class=\"fu\">,</span>                        <span class=\"er\">//</span> <span class=\"er\">innholdet</span> <span class=\"er\">—</span> <span class=\"er\">se</span> <span class=\"er\">tekstkonvensjoner</span></span>\n<span id=\"cb3-8\"><a href=\"#cb3-8\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;alts&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;label&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Mark 10,13-16&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span> <span class=\"ot\">]</span><span class=\"fu\">,</span>   <span class=\"er\">//</span> <span class=\"er\">varianter</span> <span class=\"er\">(enten/eller)</span></span>\n<span id=\"cb3-9\"><a href=\"#cb3-9\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;selAlt&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">0</span><span class=\"fu\">,</span>                        <span class=\"er\">//</span> <span class=\"er\">valgt</span> <span class=\"er\">alternativ-indeks</span> <span class=\"er\">(0</span> <span class=\"er\">=</span> <span class=\"er\">første)</span></span>\n<span id=\"cb3-10\"><a href=\"#cb3-10\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;introAlts&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;label&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Innledning&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span> <span class=\"ot\">]</span><span class=\"fu\">,</span></span>\n<span id=\"cb3-11\"><a href=\"#cb3-11\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;selIntro&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">0</span><span class=\"fu\">,</span></span>\n<span id=\"cb3-12\"><a href=\"#cb3-12\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;avslutningAlts&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;label&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Avslutning&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;text&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;…&quot;</span> <span class=\"fu\">}</span> <span class=\"ot\">]</span><span class=\"fu\">,</span></span>\n<span id=\"cb3-13\"><a href=\"#cb3-13\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;selAvsl&quot;</span><span class=\"fu\">:</span> <span class=\"dv\">0</span><span class=\"fu\">,</span></span>\n<span id=\"cb3-14\"><a href=\"#cb3-14\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;enabled&quot;</span><span class=\"fu\">:</span> <span class=\"kw\">true</span><span class=\"fu\">,</span>                    <span class=\"er\">//</span> <span class=\"er\">false</span> <span class=\"er\">=</span> <span class=\"er\">tatt</span> <span class=\"er\">ut</span> <span class=\"er\">av</span> <span class=\"er\">gudstjenesten</span></span>\n<span id=\"cb3-15\"><a href=\"#cb3-15\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;optional&quot;</span><span class=\"fu\">:</span> <span class=\"kw\">false</span><span class=\"fu\">,</span>                  <span class=\"er\">//</span> <span class=\"er\">valgfritt</span> <span class=\"er\">ledd</span></span>\n<span id=\"cb3-16\"><a href=\"#cb3-16\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;salmeNr&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;&quot;</span><span class=\"fu\">,</span>                      <span class=\"er\">//</span> <span class=\"er\">bare</span> <span class=\"er\">type</span> <span class=\"dt\">&quot;salme&quot;</span></span>\n<span id=\"cb3-17\"><a href=\"#cb3-17\" aria-hidden=\"true\" tabindex=\"-1\"></a>  <span class=\"dt\">&quot;salmeTittel&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;&quot;</span>                   <span class=\"er\">//</span> <span class=\"er\">bare</span> <span class=\"er\">type</span> <span class=\"st\">&quot;salme&quot;</span></span>\n<span id=\"cb3-18\"><a href=\"#cb3-18\" aria-hidden=\"true\" tabindex=\"-1\"></a><span class=\"fu\">}</span></span></code></pre></div>\n<p>Minimum: <code>id</code>, <code>type</code>, <code>heading</code>,\n<code>text</code>, <code>alts</code>, <code>selAlt</code>.\n<code>heading</code> uten <code>* </code>-prefiks = alltid med.\n<code>type: \"salme\"</code>-ledd bruker\n<code>salmeNr</code>/<code>salmeTittel</code> i stedet for tekst.</p>\n<h2 id=\"tekstkonvensjoner-viktigst-for-konvertering\">Tekstkonvensjoner\n(viktigst for konvertering)</h2>\n<h3 id=\"roller\">Roller</h3>\n<p>Rollemerker skrives som <code>{{r}}ROLLE |{{/r}}</code> først på\nlinjen, deretter teksten. Rollene skilles med <code>/</code>:</p>\n<pre><code>{{r}}L |{{/r}} I Faderens og Sønnens og Den hellige ånds navn.\n{{r}}ML/L |{{/r}} De bar små barn til Jesus …</code></pre>\n<p>Vanlige roller: <code>L</code> (liturg), <code>ML</code> (medliturg),\n<code>ML/L</code>, <code>K</code> (kongebaru),\n<code>Alle</code>/<code>M</code> (menighet). Tekst uten rollemerke =\nmenighet/tale.</p>\n<h3 id=\"bibelreferanser--bibelref-\">Bibelreferanser —\n<code>BIBELREF |</code></h3>\n<p>Bibeltekster avsluttes med en referanselinje:</p>\n<pre><code>BIBELREF | Joh 3,16\nBIBELREF | Mark 10,13-16</code></pre>\n<p>Referanselinjen ligger SIST i <code>text</code> (etter\n<code>\\n</code>).</p>\n<h3 id=\"instruksjoner--notat\">Instruksjoner — <code>@NOTAT</code></h3>\n<p>Rubrikker/stageinstruksjoner i docx («Rubrikk»-stil) blir\n<code>instr</code>-feltet, eller <code>@NOTAT</code>-linjer i\nteksten:</p>\n<pre><code>@NOTAT Klokkeringing\n@NOTAT Her kan liturgen si noe kortfattet om den aktuelle dåpshandlingen.</code></pre>\n<h3 id=\"sideskift--sideskift\">Sideskift — <code>sideskift</code></h3>\n<p>Et ledd kan markeres med <code>\"sideskift\": true</code>\n(kontekstmenyen: «Sideskift før dette leddet»). I Word/PDF-eksporten\nstarter leddet på en ny side; sidetallet fortsetter. PPTX er ikke berørt\n(hvert ledd er allerede egne slides).</p>\n<h3 id=\"opphavsrett--copyright-\">Opphavsrett —\n<code>@COPYRIGHT |</code></h3>\n<p>Salmeinfo/copyright-linjer:\n<code>@COPYRIGHT | Tekst/Melodi/© …</code> (kan fjernes fra eksport per\ndokument).</p>\n<h3 id=\"alternativer-i-teksten\">Alternativer i teksten</h3>\n<p>Flere varianter av samme ledd = <code>alts[]</code> (label = gjerne\nbibelreferansen), ikke gjentatte ledd. «Eller»-rubrikken i\nkildedokumentet skiller variantene.</p>\n<h2 id=\"konverteringsregler-docxpdf--limal\">Konverteringsregler\n(docx/pdf → .limal)</h2>\n<ol type=\"1\">\n<li><strong>Hoveddeler</strong>: <code>Heading 1</code> (docx) eller\nnummererte/ROMERTALL-titler → ny seksjon. Behold nummereringen i\ntittelen hvis kilden har den.</li>\n<li><strong>Leddtitler</strong>: <code>Heading 2/3</code> eller «nummer\n+ tittel» («2 Hilsen») → <code>heading</code> med\n<code>* </code>-prefiks hvis menigheten står under leddet. Valgfrie ledd\nmarkeres med <code>optional: true</code> (typisk der kilden sier «Her\nkan følge …»), ikke med <code>* </code>.</li>\n<li><strong>Rubrikker</strong> (docx-stil <code>Rubrikk</code>,\nrød/kursiv tekst) → <code>instr</code>-feltet (eller\n<code>@NOTAT</code>-linjer).</li>\n<li><strong>Roller</strong>: fet prefiks før <code>|</code>\n(<code>L |</code>, <code>ML/L |</code>) →\n<code>{{r}}ROLLE |{{/r}}</code>.</li>\n<li><strong>Bibelreferanser</strong>: linje som kun inneholder en\nreferanse («Joh 3,16», «Mark 10,13–16») rett etter et ledd →\n<code>BIBELREF | &lt;ref&gt;</code> på sluten av leddets\n<code>text</code>, og gjerne som <code>alts</code>-label.</li>\n<li><strong>«Eller»-rubrikker</strong>: følgende tekstinntil neste\ntittel/rubrikk blir et nytt alternativ i <code>alts[]</code> på samme\nledd.</li>\n<li><strong>Salmer</strong>: «Nr. X»/tittel-kombinasjoner →\n<code>type: \"salme\"</code> med\n<code>salmeNr</code>/<code>salmeTittel</code>.</li>\n<li><strong>Målform/type</strong>: sett <code>malForm</code> og\n<code>liturgiType</code> eksplisitt.</li>\n<li>Valider alltid resultatet ved å åpne <code>.limal</code>-filen i\nappen (Bibliotek → Maler → importer) før den anses som ferdig.</li>\n</ol>\n";
export const malsprakHtml = "<h1 id=\"malspråket-for-prekenforberedelse\">Malspråket for\nprekenforberedelse</h1>\n<p>Malene for prekenforberedelse-filene bruker <strong>EJS</strong>\n(npm-pakken ejs, samme malmotor som brukes overalt i Node-verdenen). En\nmal gir innholdet til én fil: skriver du malen for\n<code>notat.md</code>, blir utdataet md-tekst som lages til notat.md –\neller notat.docx hvis filformatet er Word.</p>\n<p>Fordi malene er ekte EJS kan du bruke full JavaScript i malene –\nvariabler, løkker, betingelser og funksjoner – uten at noe må bygges\nspesielt inn i appen.</p>\n<h2 id=\"malsyntaks\">Malsyntaks</h2>\n<ul>\n<li><code>&lt;%= uttrykk %&gt;</code> sender ut verdien (escaper\nHTML-tegn; i md- og docx-filer er det ufarlig).</li>\n<li><code>&lt;%- uttrykk %&gt;</code> sender ut verdien rå (uten\nescaping) – anbefalt for md/docx.</li>\n<li><code>&lt;% kode %&gt;</code> kjører JavaScript uten å sende ut noe:\n<code>&lt;% if (...) { %&gt; ... &lt;% } %&gt;</code>.</li>\n<li>Betingelser:\n<code>&lt;% if (dag.bonn) { %&gt; ... &lt;% } %&gt;</code>.</li>\n<li>Løkker:\n<code>&lt;% for (const t of [tekster.E, tekster.L1]) { %&gt; ... &lt;% } %&gt;</code>.</li>\n<li>Alt av JS virker betinget av hva konteksten inneholder.</li>\n</ul>\n<h2 id=\"konteksten-variablene-du-kan-bruke\">Konteksten: variablene du\nkan bruke</h2>\n<p>Malen får et objekt med tre deler: <code>dag</code>,\n<code>tekster</code> og <code>kirkeaar</code>. Alt hentes fra\nkirkeårsmodulen for den dagen prekenforberedelsen startes fra.</p>\n<h3 id=\"dag---kirkeårsdagen\">dag - kirkeårsdagen</h3>\n<table>\n<thead>\n<tr>\n<th>Variabel</th>\n<th>Betydning</th>\n<th>Eksempel</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>&lt;%= dag.navn %&gt;</code></td>\n<td>Dagens navn</td>\n<td>Julaften</td>\n</tr>\n<tr>\n<td><code>&lt;%= dag.dato %&gt;</code></td>\n<td>ISO-dato (y-m-d)</td>\n<td>2026-12-24</td>\n</tr>\n<tr>\n<td><code>&lt;%= dag.datoTekst %&gt;</code></td>\n<td>Ukedag og dato på norsk</td>\n<td>torsdag 24. desember 2026</td>\n</tr>\n<tr>\n<td><code>&lt;%= dag.farge %&gt;</code></td>\n<td>Liturgisk farge</td>\n<td>Hvit</td>\n</tr>\n<tr>\n<td><code>&lt;%= dag.rekke %&gt;</code></td>\n<td>Tekstrekken (hovedrekke I/II/III eller alternativ)</td>\n<td>Andre</td>\n</tr>\n<tr>\n<td><code>&lt;%= dag.periode %&gt;</code></td>\n<td>Periodeopplysning (tom hvis ingen)</td>\n<td>Adventstid</td>\n</tr>\n<tr>\n<td><code>&lt;%= dag.bonn %&gt;</code></td>\n<td>Dagens bønn (tom hvis ingen)</td>\n<td>Herre, vår Gud ...</td>\n</tr>\n</tbody>\n</table>\n<h3 id=\"tekster---lesningene-fra-tekstcachen\">tekster - lesningene fra\ntekstcachen</h3>\n<p>Hver av <code>tekster.E</code>, <code>tekster.L1</code> og\n<code>tekster.L2</code> (Evangelium, første og andre lesning) er et\nobjekt med fem felter:</p>\n<table>\n<thead>\n<tr>\n<th>Variabel</th>\n<th>Betydning</th>\n<th>Eksempel</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>&lt;%= tekster.E.ref %&gt;</code></td>\n<td>Referansen som tekst (tom hvis mangler)</td>\n<td>Matt 1,18-25</td>\n</tr>\n<tr>\n<td><code>&lt;%= tekster.E.refVis %&gt;</code></td>\n<td>Referansetekst med fallback: <code>—</code> hvis tom</td>\n<td>Matt 1,18-25</td>\n</tr>\n<tr>\n<td><code>&lt;%= tekster.E.tittel %&gt;</code></td>\n<td>Tekstens overskrift fra tekstcachen</td>\n<td>Jes 7,10-16</td>\n</tr>\n<tr>\n<td><code>&lt;%= tekster.E.tekst %&gt;</code></td>\n<td>Selve bibelteksten</td>\n<td>...</td>\n</tr>\n<tr>\n<td><code>&lt;%= tekster.E.harInnhold %&gt;</code></td>\n<td>Sant hvis tittel eller tekst finnes</td>\n<td>true/false</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>Hvis teksten ikke er cachet ennå, er tittel og tekst tomme og\n<code>harInnhold</code> er falsk.</li>\n<li>Bibeltekst-cache-fyller feltene i bakgrunnen ved oppstart, så\ninnholdet blir tilgjengelig første dagene du bruker appen.</li>\n</ul>\n<h3 id=\"kirkeaar---kirkeåret\">kirkeaar - kirkeåret</h3>\n<table>\n<thead>\n<tr>\n<th>Variabel</th>\n<th>Betydning</th>\n<th>Eksempel</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>&lt;%= kirkeaar.start %&gt;</code></td>\n<td>Startåret for kirkeåret</td>\n<td>2026</td>\n</tr>\n<tr>\n<td><code>&lt;%= kirkeaar.slutt %&gt;</code></td>\n<td>Sluttåret</td>\n<td>2027</td>\n</tr>\n<tr>\n<td><code>&lt;%= kirkeaar.rekke %&gt;</code></td>\n<td>Mappenavnet: rekkes navn</td>\n<td>Andre</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"eksempel---egendefinert-notatmal\">Eksempel - egendefinert\nnotatmal</h2>\n<pre class=\"text\"><code># &lt;%= dag.navn %&gt; (&lt;%= dag.dato %&gt;)\n\nRekke: &lt;%= dag.rekke %&gt; | Kirkeår &lt;%= kirkeaar.start %&gt;-&lt;%= kirkeaar.slutt %&gt;\nFarge: &lt;%= dag.farge %&gt;\n\n&lt;% if (dag.bonn) { %&gt;\n## Dagens bønn\n\n&lt;%= dag.bonn %&gt;\n&lt;% } %&gt;\n\n## Evangelium\n\n&lt;% if (tekster.E.harInnhold) { %&gt;**&lt;%= tekster.E.tittel %&gt;**\n&lt;%= tekster.E.tekst %&gt;&lt;% } else { %&gt;*(teksten kommer når den er cachet)*&lt;% } %&gt;\n\n&lt;% for (const [navn, t] of [[&quot;Første lesning&quot;, tekster.L1], [&quot;Andre lesning&quot;, tekster.L2]]) { %&gt;\n## &lt;%= navn %&gt;&lt;% if (t.ref) { %&gt; — &lt;%= t.ref %&gt;&lt;% } %&gt;\n\n&lt;%= t.tekst || &#39;&#39; %&gt;\n&lt;% } %&gt;</code></pre>\n<h2 id=\"word-docx-og-forhåndsvisning\">Word (.docx) og\nforhåndsvisning</h2>\n<ul>\n<li>Markdown-innholdet følger oversetteren til Word: overskrifter (# til\n####), punktliste, nummerert liste, <strong>utheving</strong>,\n<em>kursiv</em> og tabeller (<code>|</code>-linjer).</li>\n<li>Forhåndsvisningen i mal-redigeringen kjører mot eksempel dagen\nJulaften; datoer og tekster der kan avvike fra din valgte dag.</li>\n<li>Feil i en mal stopper ikke genereringen: fila blir tom, og du får en\nfeilmelding med navnet på den feilende malen.</li>\n</ul>\n";
